1145			{"only uppercase apply index zero", `"APPLIEDINDEX":0`, 0, nil},
1146			{"only uppercase nonzero apply index", `"APPLIEDINDEX":5`, 5, nil},
1147			{"only mixed-case apply error object",
1148				`"aPpLyErRoR":{"index":3,"reason":"boom"}`, 0,
1149				map[string]any{"index": float64(3), "reason": "boom"}},
1150			{"capitalized index with capitalized error",
1151				`"AppliedIndex":4,"ApplyError":{"index":6,"reason":"bad"}`, 4,
1152				map[string]any{"index": float64(6), "reason": "bad"}},
1153		}
1154		for _, tc := range cases {
