1156				data := `{"accepted":true,"reason":"ok","term":2,"committedIndex":1,` + tc.extra + `}`
1157				var result AppendResult
1158				if err := json.Unmarshal([]byte(data), &result); err != nil {
1159					t.Fatal(err)
1160				}
1161				reencoded, err := json.Marshal(result)
1162				if err != nil {
1163					t.Fatal(err)
1164				}
1165				m := decodeMap(t, reencoded)
1166				// 必须以标准字段名输出，原始大小写名不得残留。
1167				mustHaveKeys(t, m, "per-request result", "appliedIndex", "applyError")
