1211				`"FINALAPPLYERROR":{"index":2,"reason":"` + ApplyReasonSetMissingEquals + `"}`, 0,
1212				map[string]any{},
1213				map[string]any{"index": float64(2), "reason": ApplyReasonSetMissingEquals}},
1214		}
1215		for _, tc := range cases {
1216			t.Run(tc.name, func(t *testing.T) {
1217				data := `{"results":[],"finalTerm":2,"finalCommittedIndex":1,` +
1218					`"finalLog":[{"index":1,"term":1,"command":"set a=1"}],` + tc.extra + `}`
1219				var out ReplicateOutput
1220				if err := json.Unmarshal([]byte(data), &out); err != nil {
1221					t.Fatal(err)
1222				}
1223				reencoded, err := json.Marshal(out)
1224				if err != nil {
1225					t.Fatal(err)
1226				}
1227				m := decodeMap(t, reencoded)
1228				// 三个标准字段名必须带齐，原始大小写名不得残留。
1229				mustHaveKeys(t, m, "final output",
1230					"finalAppliedIndex", "finalKV", "finalApplyError")
1231				for _, variant := range []string{
1232					"FINALAPPLIEDINDEX", "FinalAppliedIndex", "fInAlKv",
1233					"FINALKV", "FinalKV", "FINALAPPLYERROR", "FinalApplyError",
1234				} {
1235					if _, ok := m[variant]; ok {
1236						t.Fatalf("case-variant key %q leaked into output: %v", variant, m)
1237					}
1238				}
1239				if m["finalAppliedIndex"] != tc.wantIndex {
1240					t.Fatalf("finalAppliedIndex = %v, want %v: %v",
1241						m["finalAppliedIndex"], tc.wantIndex, m)
1242				}
1243				if !reflect.DeepEqual(m["finalKV"], tc.wantKV) {
1244					t.Fatalf("finalKV = %v, want %v", m["finalKV"], tc.wantKV)
1245				}
1246				if tc.wantError == nil {
1247					if m["finalApplyError"] != nil {
1248						t.Fatalf("finalApplyError = %v, want null: %v", m["finalApplyError"], m)
1249					}
1250				} else if !reflect.DeepEqual(m["finalApplyError"], tc.wantError) {
1251					t.Fatalf("finalApplyError = %v, want %v", m["finalApplyError"], tc.wantError)
1252				}
1253				// 任期、提交位置与日志内容保持原样。
1254				if m["finalTerm"] != float64(2) || m["finalCommittedIndex"] != float64(1) {
1255					t.Fatalf("final replication fields changed: %v", m)
1256				}
1257			})
1258		}
1259	}
1260	
1261	// TestKVRoundTripCaseFoldedKeysLevelIndependent 大小写变体同样遵守两层各自判断：
1262	// 某条答复以变体名记录应用状态，不能让其他答复或最终结果凭空增加应用字段；
1263	// 最终结果以变体名记录时，反过来也一样。
1264	func TestKVRoundTripCaseFoldedKeysLevelIndependent(t *testing.T) {
1265		perRequestKeys := []string{"appliedIndex", "applyError"}
1266		finalKeys := []string{"finalAppliedIndex", "finalKV", "finalApplyError"}
1267	
1268		// 情形一：最终层以变体名记录；请求 0 无应用字段，请求 1 以变体名记录。
1269		data1 := `{"results":[` +
1270			`{"accepted":true,"reason":"ok","term":3,"committedIndex":0},` +
1271			`{"accepted":false,"reason":"stale term: leader term is lower than current term","term":3,"committedIndex":0,"APPLIEDINDEX":2,"ApplyError":{"index":3,"reason":"boom"}}` +
1272			`],"finalTerm":3,"finalCommittedIndex":0,"finalLog":[],` +
1273			`"FINALAPPLIEDINDEX":2,"FinalKV":{"k":"v"},"FINALAPPLYERROR":{"index":3,"reason":"boom"}}`
1274		var out1 ReplicateOutput
1275		if err := json.Unmarshal([]byte(data1), &out1); err != nil {
1276			t.Fatal(err)
1277		}
1278		reencoded1, err := json.Marshal(out1)
1279		if err != nil {
1280			t.Fatal(err)
1281		}
1282		m1 := decodeMap(t, reencoded1)
1283		results1 := resultMaps(t, m1)
1284		mustLackKeys(t, results1[0], "plain request", perRequestKeys...)
1285		mustHaveKeys(t, results1[1], "applied request", perRequestKeys...)
1286		if results1[1]["appliedIndex"] != float64(2) ||
1287			!reflect.DeepEqual(results1[1]["applyError"],
1288				map[string]any{"index": float64(3), "reason": "boom"}) {
1289			t.Fatalf("applied request values changed: %v", results1[1])
1290		}
1291		mustHaveKeys(t, m1, "final output", finalKeys...)
1292		if !reflect.DeepEqual(m1["finalKV"], map[string]any{"k": "v"}) {
1293			t.Fatalf("finalKV changed: %v", m1["finalKV"])
1294		}
1295	
1296		// 情形二：只有请求 0 以变体名记录；最终层与请求 1 必须保持无应用字段。
1297		data2 := `{"results":[` +
1298			`{"accepted":true,"reason":"ok","term":1,"committedIndex":0,"AppliedIndex":0,"APPLYERROR":null},` +
1299			`{"accepted":true,"reason":"ok","term":1,"committedIndex":0}` +
1300			`],"finalTerm":1,"finalCommittedIndex":0,"finalLog":[]}`
1301		var out2 ReplicateOutput
1302		if err := json.Unmarshal([]byte(data2), &out2); err != nil {
1303			t.Fatal(err)
1304		}
1305		reencoded2, err := json.Marshal(out2)
1306		if err != nil {
1307			t.Fatal(err)
1308		}
1309		m2 := decodeMap(t, reencoded2)
1310		results2 := resultMaps(t, m2)
1311		mustHaveKeys(t, results2[0], "applied request", perRequestKeys...)
1312		if results2[0]["appliedIndex"] != float64(0) || results2[0]["applyError"] != nil {
1313			t.Fatalf("applied request values changed: %v", results2[0])
1314		}
1315		mustLackKeys(t, results2[1], "plain request", perRequestKeys...)
1316		mustLackKeys(t, m2, "final output", finalKeys...)
1317	}
1318	
1319	// TestKVRoundTripSimilarKeysDoNotTrigger 与应用字段名相似但大小写折叠后仍不
1320	// 相同的无关键，不能触发应用字段补齐；输出形状与完全没有应用字段的旧结果一致。
1321	func TestKVRoundTripSimilarKeysDoNotTrigger(t *testing.T) {
1322		perRequestSimilar := []string{
1323			`"myAppliedIndex":9`,
1324			`"appliedIndex2":9`,
1325			`"applied_index":9`,
1326			`"ApplyErrors":null`,
1327			`"xapplyError":null`,
1328		}
1329		for _, extra := range perRequestSimilar {
1330			data := `{"accepted":true,"reason":"ok","term":1,"committedIndex":0,` + extra + `}`
1331			var result AppendResult
1332			if err := json.Unmarshal([]byte(data), &result); err != nil {
1333				t.Fatalf("decode %s: %v", data, err)
1334			}
1335			reencoded, err := json.Marshal(result)
1336			if err != nil {
1337				t.Fatal(err)
1338			}
1339			m := decodeMap(t, reencoded)
1340			mustLackKeys(t, m, "result with "+extra, "appliedIndex", "applyError")
1341			if result.applyFields {
1342				t.Fatalf("similar key %q must not open apply fields switch", extra)
1343			}
1344		}
1345	
1346		finalSimilar := []string{
1347			`"finalAppliedIndexV2":9`,
1348			`"finalKVVersion":{}`,
1349			`"finalApplyErrorCode":null`,
1350			`"FinalAppliedIndex2":1`,
1351			`"FINAL_KV":{}`,
1352		}
1353		for _, extra := range finalSimilar {
1354			data := `{"results":[],"finalTerm":1,"finalCommittedIndex":0,"finalLog":[],` + extra + `}`
1355			var out ReplicateOutput
1356			if err := json.Unmarshal([]byte(data), &out); err != nil {
1357				t.Fatalf("decode %s: %v", data, err)
1358			}
1359			reencoded, err := json.Marshal(out)
1360			if err != nil {
1361				t.Fatal(err)
1362			}
1363			m := decodeMap(t, reencoded)
1364			mustLackKeys(t, m, "output with "+extra,
1365				"finalAppliedIndex", "finalKV", "finalApplyError")
1366			if out.applyFields {
1367				t.Fatalf("similar key %q must not open apply fields switch", extra)
1368			}
1369		}
1370	}
1371	
1372	// TestKVRoundTripCaseFoldedBadTypesRejected 应用索引写成字符串、键值表写成数组
1373	// 等现有非法类型，即使字段名换了大小写也要返回解码错误。
1374	func TestKVRoundTripCaseFoldedBadTypesRejected(t *testing.T) {
1375		badInputs := []string{
1376			`{"results":[],"finalTerm":0,"finalCommittedIndex":0,"finalLog":[],"FINALAPPLIEDINDEX":"0"}`,
1377			`{"results":[],"finalTerm":0,"finalCommittedIndex":0,"finalLog":[],"FinalKV":[]}`,
1378			`{"results":[],"finalTerm":0,"finalCommittedIndex":0,"finalLog":[],"FINALAPPLYERROR":{"index":"2","reason":"x"}}`,
1379			`{"results":[{"accepted":true,"reason":"ok","term":1,"committedIndex":0,"APPLIEDINDEX":"0"}],"finalTerm":1,"finalCommittedIndex":0,"finalLog":[]}`,
1380			`{"results":[{"accepted":true,"reason":"ok","term":1,"committedIndex":0,"ApplyError":{"index":"2","reason":"x"}}],"finalTerm":1,"finalCommittedIndex":0,"finalLog":[]}`,
1381		}
1382		for _, data := range badInputs {
1383			var out ReplicateOutput
1384			if err := json.Unmarshal([]byte(data), &out); err == nil {
1385				t.Fatalf("expected decode error for %s", data)
1386			}
1387		}
1388	}
1389	
1390	// TestKVRoundTripCaseFoldedFailedReuseKeepsPreviousResult 复用已有结果对象读入
1391	// 大小写变体字段名的非法 JSON 时必须报错，并完整保留读入前的结果（含其应用
1392	// 状态）；之后输出不能混入这次读入的任何内容，也不能被变体名打开开关。
1393	func TestKVRoundTripCaseFoldedFailedReuseKeepsPreviousResult(t *testing.T) {
1394		original := runKV(t, InitialState{CurrentTerm: 1, CommittedIndex: 1, Log: []LogEntry{
1395			entry(1, 1, "set x=1"),
1396		}},
1397			AppendRequest{Term: 1, PrevLogIndex: 1, PrevLogTerm: 1, LeaderCommit: 3,
1398				Entries: []LogEntry{entry(2, 1, "set bad"), entry(3, 1, "set k=v")}},
1399		)
1400		originalJSON, err := json.Marshal(original)
1401		if err != nil {
1402			t.Fatal(err)
1403		}
1404		badInputs := []string{
1405			// 错误位于某条请求答复内，字段名大写。
1406			`{"results":[{"accepted":true,"reason":"ok","term":9,"committedIndex":9,"APPLIEDINDEX":"3"}],"finalTerm":9,"finalCommittedIndex":9,"finalLog":[]}`,
1407			// 最终层：应用索引写成字符串，字段名首字母大写。
1408			`{"results":[],"finalTerm":9,"finalCommittedIndex":9,"finalLog":[],"FinalAppliedIndex":"9"}`,
1409			// 最终层：键值表写成数组，字段名全大写。
1410			`{"results":[],"finalTerm":9,"finalCommittedIndex":9,"finalLog":[],"FINALKV":["nope"]}`,
1411		}
1412		for _, bad := range badInputs {
1413			var out ReplicateOutput
1414			if err := json.Unmarshal(originalJSON, &out); err != nil {
1415				t.Fatal(err)
1416			}
1417			if err := json.Unmarshal([]byte(bad), &out); err == nil {
1418				t.Fatalf("expected decode error for %s", bad)
1419			}
1420			reencoded, err := json.Marshal(out)
1421			if err != nil {
1422				t.Fatal(err)
1423			}
1424			if string(reencoded) != string(originalJSON) {
1425				t.Fatalf("previous result not preserved after failed decode of %s:\nwant %s\n got %s",
1426					bad, originalJSON, reencoded)
1427			}
1428		}
1429	}
1430	
1431	// TestKVRoundTripCaseFoldedSuccessfulReuseNoResidue 复用结果对象成功读入下一份
1432	// JSON 时只保留本次内容：先读入以变体名记录应用状态的结果，再读入完全没有
1433	// 应用字段的旧结果，后一次输出不得残留前一次的键值表、错误或应用位置；反方向
1434	// （先旧后变体）则必须按本次内容补齐完整应用字段。
1435	func TestKVRoundTripCaseFoldedSuccessfulReuseNoResidue(t *testing.T) {
1436		variantApplied := `{"results":[{"accepted":true,"reason":"ok","term":1,` +
1437			`"committedIndex":1,"AppliedIndex":1,"ApplyError":null}],` +
1438			`"finalTerm":1,"finalCommittedIndex":1,` +
1439			`"finalLog":[{"index":1,"term":1,"command":"set x=1"}],` +
1440			`"FinalAppliedIndex":1,"FinalKV":{"x":"1"},"FINALAPPLYERROR":null}`
1441		plain := `{"results":[{"accepted":true,"reason":"ok","term":1,"committedIndex":1}],` +
1442			`"finalTerm":1,"finalCommittedIndex":1,` +
1443			`"finalLog":[{"index":1,"term":1,"command":"set x=1"}]}`
1444	
1445		// 先变体后旧结果：无残留。
1446		var out ReplicateOutput
1447		if err := json.Unmarshal([]byte(variantApplied), &out); err != nil {
1448			t.Fatal(err)
1449		}
1450		if err := json.Unmarshal([]byte(plain), &out); err != nil {
1451			t.Fatal(err)
1452		}
1453		body, err := json.Marshal(out)
1454		if err != nil {
1455			t.Fatal(err)
1456		}
1457		for _, field := range []string{"appliedIndex", "applyError", "finalAppliedIndex", "finalKV", "finalApplyError"} {
1458			if strings.Contains(string(body), field) {
1459				t.Fatalf("stale apply field %q after reusing object: %s", field, body)
1460			}
1461		}
1462		if out.FinalKV != nil || out.FinalAppliedIndex != nil || out.FinalApplyError != nil {
1463			t.Fatalf("stale apply state in %+v", out)
1464		}
1465	
1466		// 先旧结果后变体：按本次内容带齐标准字段。
1467		var out2 ReplicateOutput
1468		if err := json.Unmarshal([]byte(plain), &out2); err != nil {
1469			t.Fatal(err)
1470		}
1471		if err := json.Unmarshal([]byte(variantApplied), &out2); err != nil {
1472			t.Fatal(err)
1473		}
1474		body2, err := json.Marshal(out2)
1475		if err != nil {
1476			t.Fatal(err)
1477		}
1478		m := decodeMap(t, body2)
1479		mustHaveKeys(t, m, "final output",
1480			"finalAppliedIndex", "finalKV", "finalApplyError")
1481		if m["finalAppliedIndex"] != float64(1) ||
1482			!reflect.DeepEqual(m["finalKV"], map[string]any{"x": "1"}) ||
1483			m["finalApplyError"] != nil {
1484			t.Fatalf("variant-keyed apply state not restored after reuse: %v", m)
1485		}
1486		results := resultMaps(t, m)
1487		mustHaveKeys(t, results[0], "applied request", "appliedIndex", "applyError")
1488	}
