	}
	if *stepwise.FinalAppliedIndex != 2 {
		t.Fatalf("final appliedIndex = %d, want 2", *stepwise.FinalAppliedIndex)
	}
	if !reflect.DeepEqual(finalKVOf(t, stepwise), map[string]string{"balance": "200"}) {
